#!/usr/bin/env node
/**
 * Generate the spelling dictionary for everything the registry already knows.
 *
 * 87 title ids, their aliases and display names, and 53 provider ids, key names
 * and labels are all vocabulary this repository invented or inherited, and all
 * of it appears in prose, tests and identifiers. Hand-listing it in
 * cspell.json means a title added next year fails the spelling gate for no
 * reason anybody can act on - the word is not misspelt, it is simply new.
 *
 * So it is generated from `shared/registry`, which is itself generated from the
 * TypeScript sources. One place decides what a title is called, and the
 * spelling gate follows it.
 *
 *     node .github/scripts/generate-cspell-registry.mjs           # write
 *     node .github/scripts/generate-cspell-registry.mjs --check   # CI
 *
 * The hand-maintained half lives in `.github/cspell-vocabulary.txt`: upstream
 * JSON field names, game proper nouns, and the deliberate misspellings the
 * fuzzy-lookup tests need. Those cannot be derived from anything.
 */

import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), "..", "..");
const REGISTRY = join(ROOT, "shared", "registry");
const OUTPUT = join(ROOT, ".github", "cspell-registry.txt");

const HEADER = [
  "# Generated by .github/scripts/generate-cspell-registry.mjs - do not edit.",
  "#",
  "# Every title id, alias and name, and every provider id, key name and label,",
  "# taken from shared/registry. Adding a title adds its words here; nobody has",
  "# to remember. Words that cannot be derived from the registry - upstream JSON",
  "# field names, game proper nouns, the deliberate misspellings the fuzzy-lookup",
  "# tests need - belong in .github/cspell-vocabulary.txt instead.",
  "",
];

function read(name) {
  const parsed = JSON.parse(readFileSync(join(REGISTRY, name), "utf8"));
  // The generator has written both a bare array and an envelope over time.
  return Array.isArray(parsed) ? parsed : (parsed.titles ?? parsed.providers ?? []);
}

const words = new Set();

/** Split on anything that is not a letter or digit, and keep the pieces. */
function add(value) {
  if (!value) return;
  for (const part of String(value).split(/[^A-Za-z0-9]+/)) {
    // Two letters is an abbreviation cspell already knows or cannot judge.
    if (part.length > 2 && /[A-Za-z]/.test(part)) words.add(part.toLowerCase());
  }
}

for (const title of read("titles.json")) {
  add(title.id);
  add(title.name);
  for (const alias of title.aliases ?? []) add(alias);
  add(title.publisher);
}

for (const provider of read("providers.json")) {
  add(provider.id);
  add(provider.keyName);
  add(provider.label);
}

const body = [...words].sort().join("\n");
const content = `${HEADER.join("\n")}${body}\n`;

if (process.argv.includes("--check")) {
  let current = "";
  try {
    current = readFileSync(OUTPUT, "utf8");
  } catch {
    current = "";
  }
  if (current !== content) {
    console.error(
      "FAIL - .github/cspell-registry.txt is out of date.\n" +
        "       Run: node .github/scripts/generate-cspell-registry.mjs",
    );
    process.exit(1);
  }
  console.log(`ok - cspell-registry.txt matches the registry (${words.size} words)`);
} else {
  writeFileSync(OUTPUT, content, "utf8");
  console.log(`wrote .github/cspell-registry.txt (${words.size} words)`);
}
